local config = {
  ui_story_40070001_1_dialog_content = "Musik adalah hal suci di Lumopolis. Bahkan Keating yang suka berkata kasar akan memuji Aurora dan Corona dengan tulus.",
  ui_story_40070001_2_dialog_content = "Illumina ibarat band militer: seragam, kuat, dan memotivasi.",
  ui_story_40070001_3_dialog_content = "Umbraton memberikan tempo yang kelam dan misterius, bagaikan anggur klasik di bawah cahaya remang-remang, walaupun dengan aroma darah.",
  ui_story_40070001_4_dialog_content = "Aku belum pernah dengar nada Northland, tapi aku yakin pasti penuh dengan dongeng tradisional.",
  ui_story_40070001_5_dialog_content = "Aku yakin mereka semua sangat berbeda dengan Rediesel Wrench.",
  ui_story_40070001_6_dialog_content = "*Melahap Crunchy Munchy Crunch* Pantas saja itu jadi produk terpopuler kami.",
  ui_story_40070001_7_dialog_content = "Baik kualitas maupun harganya sama-sama terbaik.",
  ui_story_40070001_8_dialog_content = "Akan tambah lezat lagi kalau sambil minum air Lake Mirror. Menurut Northland Geographica...",
  ui_story_40070001_9_dialog_content = "Lake Mirror yang indah adalah \"Air mata terindah yang diteteskan sang dewa saat merasa kasihan pada para makhluk fana.\"",
  ui_story_40070001_10_dialog_content = "Namanya saja air mata dewa, jelas harganya mahal!",
  ui_story_40070001_11_dialog_content = "Terlebih lagi, bangku tempat kita duduk itu...",
  ui_story_40070001_12_dialog_content = "Jomu.",
  ui_story_40070001_13_dialog_content = "Sudah kuduga pelanggan tercintaku akan tertarik, Bos. Lagi pula, produk-produkku memang murah dan juga berkualitas tinggi.",
  ui_story_40070001_14_dialog_content = "Apa yang ingin kamu beli? Silakan tawar.",
  ui_story_40070001_15_dialog_content = "Kenapa sikapmu lembut sekali?",
  ui_story_40070001_16_dialog_content = "Lihat ke atas. Apa itu yang melayang di sana?",
  ui_story_40070001_17_dialog_content = "Paling-paling granat, model yang mudah dibawa.",
  ui_story_40070001_18_dialog_content = "Mudah dipakai dan bisa menimbulkan kerusakan besar.",
  ui_story_40070001_19_dialog_content = "Tentu saja aku juga jual itu!",
  ui_story_40070001_20_dialog_content = "Lalu... Apa yang terjadi di atas panggung itu?",
  ui_story_40070001_21_dialog_content = "Oh, mereka sedang bertarung.",
  ui_story_40070001_22_dialog_content = "Regina baru saja menggebuk kepala Eclipsite dengan gitar listrik. Hebat, ya!",
  ui_story_40070001_23_dialog_content = "Di sisi lain, Barbara membelah Eclipsite lain jadi dua pada pinggangnya dengan gergaji listrik modifikasinya.",
  ui_story_40070001_24_dialog_content = "Kamu butuh sekantung Crunchy Munchy Crunch lagi untuk momen-momen seru seperti ini.",
  ui_story_40070001_25_dialog_content = "Hanya 300 Nightium untuk sekantung kecil, jangan lewatkan tawaran ini!",
  ui_story_40070001_26_dialog_content = "Tidak, bukan itu masalahnya...",
  ui_story_40070001_27_dialog_content = "Tendang keluar semua Eclipsite-nya dari panggung. Mereka tidak pantas ada di sini!",
  ui_story_40070001_28_dialog_content = "Akan kutembak... Tepat sasaran!",
  ui_story_40070001_29_dialog_content = "Apanya yang tepat sasaran?! Hampir kena kepalaku, tahu?! Pasti tadi itu sengaja!",
  ui_story_40070001_30_dialog_content = "Sekarang mereka bertengkar...",
  ui_story_40070001_31_dialog_content = "Padahal harusnya ini cuma <color=#FFB400>konser biasa</color>!",
  ui_story_40070001_32_dialog_content = "Masalah ini bermula dari kurangnya jumlah penonton untuk konser Fiery Support...",
  ui_story_40070001_33_dialog_content = "Ya, kami memang akan \"memberikan pertunjukan terbaik sekalipun hanya ada satu penonton\".",
  ui_story_40070001_34_dialog_content = "Tapi kalau penontonnya terlalu sedikit, konsernya tidak akan jadi seru.",
  ui_story_40070001_35_dialog_content = "Kita sudah kirim undangan kepada para penggemar di mana-mana, 'kan? Mereka tidak membalas?",
  ui_story_40070001_36_dialog_content = "Ini balasan dari Shadowlord...",
  ui_story_40070001_37_dialog_content = "\"Terima kasih atas undangan kalian, tapi aku dan anak buahku tidak bisa menemukan tuksedo yang cocok untuk padang pasir, jadi kami takkan hadir.\"",
  ui_story_40070001_38_dialog_content = "Yang ini dari Hiiro, Legion Commander Illumina...",
  ui_story_40070001_39_dialog_content = "\"Karena jadwal Illumina yang ruwet, aku tidak bisa menyempatkan waktu.\"",
  ui_story_40070001_40_dialog_content = "\"Harap kirimkan undangan dua minggu sebelum acara.\"",
  ui_story_40070001_41_dialog_content = "Berarti sisanya hanya <color=#FFB400>Lumopolis</color> dan <color=#FFB400>Northland</color>.",
  ui_story_40070001_42_dialog_content = "Lupakan Lumopolis. Orang-orang sok penting itu takkan pernah mau menonton konser kita.",
  ui_story_40070001_43_dialog_content = "Odi meretas saluran komunikasi mereka hanya supaya bisa adu mulut dengan penjaga di sana.",
  ui_story_40070001_44_dialog_content = "Sementara untuk Northland, kami sama sekali tak dapat balasan.",
  ui_story_40070001_45_dialog_content = "Terkadang aku merasa Northland sebenarnya tidak ada.",
  ui_story_40070001_46_dialog_content = "Aku punya ide.",
  ui_story_40070001_47_dialog_content = "Undang PlayerName?",
  ui_story_40070001_48_dialog_content = "PlayerName sudah jadi orang pertama yang diundang.",
  ui_story_40070001_49_dialog_content = "Aku sudah mengingatkan Jomu untuk mengirimkan tiket kepada PlayerName...",
  ui_story_40070001_50_dialog_content = "Seandainya PlayerName tidak dapat tiketnya, aku akan menelanjangi Jomu dan menjadikan dia makanan Eclipsite.",
  ui_story_40070001_51_dialog_content = "Tapi PlayerName saja takkan cukup menggantikan seluruh penontonnya.",
  ui_story_40070001_52_dialog_content = "Jadi, kita harus mengundang penonton lain...",
  ui_story_40070001_53_dialog_content = "Biar kutebak, Regina menyarankan menculik sejumlah <color=#FFB400>Eclipsite</color> dan mengancam mereka untuk menonton?",
  ui_story_40070001_54_dialog_content = "Hei, hei, itu tidak sepenuhnya benar. Setidaknya, aku tidak ikut-ikutan!",
  ui_story_40070001_55_dialog_content = "Lagi pula, kemampuan tempurku tidak begitu hebat...",
  ui_story_40070001_56_dialog_content = "Kalau tidak ada setumpuk Nightium di depanku, aku sama sekali tidak ada niat untuk bergerak.",
  ui_story_40070001_57_dialog_content = "Sebenarnya rencana Regina tidak begitu buruk, setidaknya pada awalnya para Eclipsite mau mendengarkan dengan baik...",
  ui_story_40070001_58_dialog_content = "<color=#e8d9bb>Tempat Konser Fiery Support</color>",
  ui_story_40070001_59_dialog_content = "Hadirin sekalian, <color=#FFB400>Konser Fiery Support</color> tahunan yang diadakan berkali-kali akan segera dimulai!",
  ui_story_40070001_60_dialog_content = "Berkat Nightium tercinta, aku akan jadi pembawa acara konser ini!",
  ui_story_40070001_61_dialog_content = "Wah, wah... Bangku penonton dipenuhi oleh Rediesel Wrench dan kawan-kawannya.",
  ui_story_40070001_62_dialog_content = "PlayerName yang malang duduk tepat di bagian tengah baris terdepan, dengan wajah mual seakan-akan terkena sengatan panas.",
  ui_story_40070001_63_dialog_content = "Di belakangnya ada 1, 2, 3, 4... Sekitar 100 Eclipsite.",
  ui_story_40070001_64_dialog_content = "Meski diikat, mereka telah datang untuk menikmati konser ini.",
  ui_story_40070001_65_dialog_content = "...",
  ui_story_40070001_66_dialog_content = "(Astaga, kenapa ada banyak sekali Eclipsite di sini?)",
  ui_story_40070001_67_dialog_content = "(Aku tahu konser Rediesel Wrench itu menyeramkan, tapi tak kusangka bahwa aku bakal duduk bersebelahan dengan Eclipsite!)",
  ui_story_40070001_68_dialog_content = "Ini... Seram... *Muntah*",
  ui_story_40070001_69_dialog_content = "(Kenapa Eclipsite-nya lebih ketakutan daripada aku?)",
  ui_story_40070001_70_dialog_content = "Tenanglah, PlayerName. Kamu sudah akrab dengan Eclipsite di sebelahmu, ya?",
  ui_story_40070001_71_dialog_content = "Sebentar lagi aku akan turun ke sana, tapi jangan lupa beri tip untukku, ya!",
  ui_story_40070001_72_dialog_content = "Baiklah, mari kita sambut bintang acara ini!",
  ui_story_40070001_73_dialog_content = "Sang matahari hitam yang membara di atas Rediesel Desert...",
  ui_story_40070001_X73_dialog_content = "<size=45><color=#FFB400>Regina!</color></size>",
  ui_story_40070001_74_dialog_content = "Ini baru namanya konser. Menculik Eclipsite itu ide yang tepat.",
  ui_story_40070001_75_dialog_content = "*Groar*",
  ui_story_40070001_76_dialog_content = "Ditemani juga dengan idola paling populer dari Rediesel Wrench.",
  ui_story_40070001_77_dialog_content = "Dengan energi dan kemanisan yang bisa melelehkan kalian, idola kesukaan semua...",
  ui_story_40070001_X77_dialog_content = "<size=45><color=#FFB400>Barbara!</color></size>",
  ui_story_40070001_78_dialog_content = "Dia penyanyi dari grupku, jadi jangan lupa berikan dukungan dengan dompet kalian, ya!",
  ui_story_40070001_79_dialog_content = "Aku sayang kalian semua!",
  ui_story_40070001_80_dialog_content = "Aku bisa dengar suara kalian, tapi pasti kalian bisa bersuara lebih keras lagi!",
  ui_story_40070001_81_dialog_content = "Gha... Graaaah!",
  ui_story_40070001_82_dialog_content = "Bagus!",
  ui_story_40070001_83_dialog_content = "Baiklah, panggung akan kuserahkan pada mereka berdua!",
  ui_story_40070001_84_dialog_content = "Ughaaa! Urraagh!",
  ui_story_40070001_85_dialog_content = "Sudah cukup bacotnya dan mainkan saja musiknya, dasar kue sus goreng!",
  ui_story_40070001_86_dialog_content = "Bilang apa kamu, belatung Sandworm bersinar? Kali ini aku akan melumatmu!",
  ui_story_40070001_87_dialog_content = "<color=#e8d9bb>Suara musik kencang mendadak membuat kuping berdenging, dan kedua penyanyi tersebut meraih mik mereka dengan semangat.</color>",
  ui_story_40070001_88_dialog_content = "\"Akulah <color=#FFB400>matahari hitam</color> yang bisa membakar segalanya!\"",
  ui_story_40070001_89_dialog_content = "\"Bara semangat, panggung, dan udara ada dalam kendaliku!\"",
  ui_story_40070001_90_dialog_content = "\"Sudah jadi peranmu untuk dilukai kata-kata dan sikapku!\"",
  ui_story_40070001_91_dialog_content = "\"Tak ada yang bisa menahan badai surya yang gemerlap!\"",
  ui_story_40070001_92_dialog_content = "\"Ini punchline Barbara... <color=#FFB400>Aku suka suka suka kalian semua</color>!\"",
  ui_story_40070001_93_dialog_content = "\"Kalau kamu sampai emosi, berarti otakmu sudah basi!\"",
  ui_story_40070001_94_dialog_content = "\"Kamu memang pengecut, tapi masa sama musik jadi takut!\"",
  ui_story_40070001_95_dialog_content = "\"Melodiku itu penghasil emas, ayo ikuti sampai lemas.\"",
  ui_story_40070001_96_dialog_content = "\"Kamu ini sukanya main kasar, kenapa pakai berlagak imut?\"",
  ui_story_40070001_97_dialog_content = "\"Pakai goda-goda Eclipsite segala, kamu ini berharap apa?\"",
  ui_story_40070001_98_dialog_content = "\"Gayamu yang terus memakai cinta palsu membuatku muaaaak!\"",
  ui_story_40070001_99_dialog_content = "\"Musik kamu tak ada jiwanya, cuma karya gagal!\"",
  ui_story_40070001_100_dialog_content = "\"Tidak punya otak, tapi ngaku-ngaku matahari hitam, lebih mirip lubang hitam!\"",
  ui_story_40070001_101_dialog_content = "\"Kacung Sinsa, mikir sendiri juga tak bisa!\"",
  ui_story_40070001_102_dialog_content = "\"Pengecut tidak berani main, bisanya andalkan orang lain!\"",
  ui_story_40070001_103_dialog_content = "\"Mending kamu ke Lumopolis, eh, maaf, mereka tidak terima pengemis!\"",
  ui_story_40070001_104_dialog_content = "(Oke, mereka tidak terdengar seperti menyanyi, tapi justru saling menghina!)",
  ui_story_40070001_105_dialog_content = "(Tapi bukan itu yang kukhawatirkan di tengah semua Eclipsite ini...)",
  ui_story_40070001_106_dialog_content = "Tunggu, apa itu yang naik ke panggung?",
  ui_story_40070001_107_dialog_content = "Awas, ada Eclipsite!",
  ui_story_40070001_108_dialog_content = "Tiny One?!",
  ui_story_40070001_109_dialog_content = "Untungnya, aku bisa menyerang dengan <color=#FFB400>Super Cool Spotlight</color> yang kubuat.",
  ui_story_40070001_110_dialog_content = "Itu bukannya juga dipakai buat menyorot orang di panggung?",
  ui_story_40070001_111_dialog_content = "Iya.",
  ui_story_40070001_112_dialog_content = "Kamu benar-benar berencana menyorot orang dengan benda itu? Padahal itu membuat Eclipsite yang tadi jadi gosong.",
  ui_story_40070001_113_dialog_content = "Terus kenapa?",
  ui_story_40070001_114_dialog_content = "Gawat, Eclipsite-nya lepas!",
  ui_story_40070001_115_dialog_content = "Aneh, padahal mereka diikat dengan tali terbaik yang aku punya!",
  ui_story_40070001_116_dialog_content = "Mereka menyerbu panggung!",
  ui_story_40070001_117_dialog_content = "Lalu setelah itu, konsernya menjadi ajang keributan.",
  ui_story_40070001_118_dialog_content = "Kamu memang hebat, hafal semua sampai ke detailnya!",
  ui_story_40070001_119_dialog_content = "Berminat untuk bantu-bantu aku berjualan?",
  ui_story_40070001_120_dialog_content = "Jumlah mereka banyak sekali. Kita memang menculik sekitar seratusan, sih.",
  ui_story_40070001_121_dialog_content = "Duh, membunuh itu tidak cocok dengan gambaran Barbara sebagai idola pop.",
  ui_story_40070001_122_dialog_content = "Rasakan ini!",
  ui_story_40070001_123_dialog_content = "Entah bagaimana, sepertinya Eclipsite-nya jadi makin banyak... Bagaimana ini?",
  ui_story_40070001_124_dialog_content = "<size=45>Berhenti!</size>",
  ui_story_40070001_125_dialog_content = "Siapa itu?",
  ui_story_40070001_126_dialog_content = "Hei, aku kenal suara itu!",
  ui_story_40070001_127_dialog_content = "Bukankah itu...",
  ui_story_40070001_128_dialog_content = "<color=#FFB400>Sinsa</color>?",
  ui_story_40070001_129_dialog_content = "Berani-beraninya kalian mengadakan konser tanpa aku?",
  ui_story_40070001_130_dialog_content = "Aku sudah menyiapkan satu lagu. Bagaimana kalau berkelahinya nanti saja setelah aku selesai menyanyi?",
  ui_story_40070001_131_dialog_content = "<color=#e8d9bb>Semuanya berhenti bertarung.</color>",
  ui_story_40070001_132_dialog_content = "Luar biasa! Seisi tempat ini jadi terdiam!",
  ui_story_40070001_133_dialog_content = "Hanya gelegar suara langkahnya yang terdengar.",
  ui_story_40070001_134_dialog_content = "Perhatian semua orang tertuju pada Sinsa.",
  ui_story_40070001_135_dialog_content = "Ehem. Tes, 1, 2.",
  ui_story_40070001_136_dialog_content = "Sepertinya kita kedatangan tamu spesial untuk konser hari ini, Sinsa! Tentunya datang terlambat, seperti biasa.",
  ui_story_40070001_137_dialog_content = "Kabarnya nyanyiannya itu setara dengan ledakan bom.",
  ui_story_40070001_138_dialog_content = "Baiklah, silakan dimulai—",
  ui_story_40070001_139_dialog_content = "<anim type=Shake>Jangan <size=45>pernah</size> lupakan <size=45>Rediesel</size> Wrench... Jangan <size=30>pernah</size> lupakan <size=45>padang</size> yang penuh pasir</anim>.",
  ui_story_40070001_140_dialog_content = "<anim type=Shake>Jangan <size=30>lupakan</size> Lepidoz... Jangan lupakan <size=45>Eve</size>.</anim>",
  ui_story_40070001_141_dialog_content = "<anim type=Shake>Oh, <size=45>Eve</size>, adikku yang paling kucintai.</anim>",
  ui_story_40070001_142_dialog_content = "Suaranya kencang sekali dan juga sumbang. Bahkan para Eclipsite sampai ketakutan.",
  ui_story_40070001_143_dialog_content = "Belum lagi, dia juga menyanyi sambil menembakkan senapan.",
  ui_story_40070001_144_dialog_content = "Jumlah Eclipsite-nya sampai menyusut.",
  ui_story_40070001_145_dialog_content = "Bos besar Sinsa memang penyanyi terbaik!",
  ui_story_40070001_146_dialog_content = "Aku setuju!",
  ui_story_40070001_147_dialog_content = "Apa? Kalian serius?",
  ui_story_40070001_148_dialog_content = "Akhirnya selesai juga... Ini pertama kalinya aku ikut konser seperti ini.",
  ui_story_40070001_149_dialog_content = "Masih ada yang kedua. Aku sudah menyiapkan tiket untukmu buat konser berikutnya, Bos!",
  ui_story_40070001_150_dialog_content = "Tidak usah. Terima kasih...",
  ui_story_40070001_151_dialog_content = "Sinsa.",
  ui_story_40070001_152_dialog_content = "Hei, bagaimana menurutmu tentang konsernya?",
  ui_story_40070001_153_dialog_content = "Seru. Saking serunya, aku kira aku bakal mati.",
  ui_story_40070001_154_dialog_content = "Perumpamaan yang bagus! Omong-omong, apa kamu tahu kenapa Rediesel Wrench mengadakan acara seperti ini?",
  ui_story_40070001_155_dialog_content = "Apa ada alasan khusus?",
  ui_story_40070001_156_dialog_content = "Hidup di Rediesel Desert itu tidak mudah. Kehidupannya sulit.",
  ui_story_40070001_157_dialog_content = "Tapi kalau kamu terus merenungkan kesedihan masa lalu, kamu akan lenyap terkubur pasir.",
  ui_story_40070001_158_dialog_content = "Karena itu, kami mengadakan konser untuk menyemangati semua orang.",
  ui_story_40070001_159_dialog_content = "Mau seputus asa apa dirimu, selama ada minuman dan musik, kita bisa terus hidup!",
  ui_story_40070001_160_dialog_content = "Eclipsite-nya sudah habis, tapi bukan berarti konsernya sudah selesai.",
  ui_story_40070001_161_dialog_content = "Aku masih bisa terus menyanyi selama 3 hari 3 malam! Tunjukkan kebolehanmu, Regina.",
  ui_story_40070001_162_dialog_content = "Itulah yang Barbara, Regina, dan seluruh Rediesel Wrench inginkan.",
  ui_story_40070001_163_dialog_content = "Ya, Barbara dan Regina berkelahi di atas panggung,",
  ui_story_40070001_164_dialog_content = "tapi mereka senang dan juga menghibur semua orang di Rediesel Wrench.",
  ui_story_40070001_165_dialog_content = "Itu benar.",
  ui_story_40070001_166_dialog_content = "Jangan pusingkan hari esok; hiduplah sesukanya di hari ini.",
  ui_story_40070001_167_dialog_content = "Omong-omong, bagaimana menurutmu dengan nyanyianku?",
  ui_story_40070001_168_dialog_content = "<color=#e8d9bb>Satu bulan kemudian</color>",
  ui_story_40070001_169_dialog_content = "Panasnya bukan main! Jadi, ini Rediesel Desert? Beda sekali dengan Northland!",
  ui_story_40070001_170_dialog_content = "Konser Fiery Support yang legendaris diadakan di sini?",
  ui_story_40070001_171_dialog_content = "Aku jadi tidak sabar! Kita sampai butuh satu bulan untuk sampai kemari!",
  ui_story_40070001_172_dialog_content = "Wow, pasirnya seperti salju, tapi panas!",
  ui_story_40070001_173_dialog_content = "Omong-omong, tempat konsernya di mana?",
  ui_story_40070001_174_dialog_content = "Aku tidak lihat ada orang di mana pun...",
  ui_story_40070001_175_dialog_content = "Jangan-jangan konsernya sudah selesai?"
}
return config
